#!/usr/bin/env bash# scripts/ops/bulk-create-adgenxai-issues.shset -euo pipefailREPO="${REPO:-brandonlacoste9-tech/adgenxai}"DRYRUN="${DRYRUN:-0}"ISSUES_FILE="${ISSUES_FILE:-scripts/ops/issues-bulk-create.json}"LIMIT="${LIMIT:-500}"command -v gh >/dev/null 2>&1 || { echo "ERROR: gh CLI is required. https://cli.github.com/"; exit 1; }command -v jq >/dev/null 2>&1 || { echo "ERROR: jq is required. https://stedolan.github.io/jq/"; exit 1; }issue_exists() {  local title="$1"  gh issue list --repo "$REPO" --state all --json title,number --limit "$LIMIT" |    jq -r --arg t "$title" '.[] | select(.title == $t) | .number' | head -n1 || true}create_issue() {  local title="$1" body="$2" labels_csv="$3" milestone="$4"  existing="$(issue_exists "$title")"  if [ -n "$existing" ]; then    echo "? Issue exists: #$existing — $title"    return 0  fi  args=(--repo "$REPO" --title "$title" --body "$body")  if [ -n "$labels_csv" ] && [ "$labels_csv" != "null" ]; then    args+=(--label "$labels_csv")  fi  if [ -n "$milestone" ] && [ "$milestone" != "null" ]; then    args+=(--milestone "$milestone")  fi  if [ "$DRYRUN" = "1" ]; then    echo "DRYRUN: gh issue create ${args[*]}"  else    echo "Creating issue: $title"    gh issue create "${args[@]}" >/dev/null && echo "? Created: $title"  fi}if [ -f "$ISSUES_FILE" ]; then  issues_json="$(cat "$ISSUES_FILE")"else  read -r -d '' issues_json <<'JSON' || true[  {    "title": "agent-mode: set up hourly health-check (sensory cortex)",    "body": "Implement hourly health-check job for sensory cortex agent. Steps:\\n1. Verify endpoints\\n2. Post telemetry to /telemetry\\n3. Create alert issue on failure\\n\\nSee Agent Mode Launch milestone.",    "labels": ["agent-mode","ops"],    "milestone": "Agent Mode Launch"  },  {    "title": "agent-mode: telemetry-processing disabled remediation task",    "body": "Remediation steps for telemetry_processing_disabled alert:\\n- Check telemetry worker service\\n- Verify queue backlog\\n- Restart worker if necessary\\n\\nAdd runbook and escalate if unresolved.",    "labels": ["agent-mode","alert"],    "milestone": "Agent Mode Launch"  }]JSONfiebash scripts/ops/bulk-create-adgenxai-issues.sh---If you want **me** to create the PR instead (I won’t act without explicit permission), reply:- **`Open PR for me (I confirm you have push rights)`** — I will push the branch and open the PR, or  - **`Open PR for me (I created a fork: <fork-URL>)`** — I will push to the fork and open a PR.Otherwise, run the PowerShell snippet above. If anything errors, paste the exact error text here and I’ll tell you the fix.# 1) Login (interactive web flow)gh auth login# choose github.com, HTTPS (or SSH), and "Web browser" when prompted.# 2) Confirm authgh auth status# Ensure it shows "Logged in to github.com as brandonlacoste9-tech"# 3) Create branch and directoriesgit fetch origingit checkout -b chore/ops/bulk-issue-createNew-Item -ItemType Directory -Force -Path scripts/ops, docs/runbooks# 4) Create the bash script$script = @'#!/usr/bin/env bash# scripts/ops/bulk-create-adgenxai-issues.sh# Bulk-create issues for adgenxai. Safe to re-run. Supports DRYRUN=1.set -euo pipefailREPO="${REPO:-brandonlacoste9-tech/adgenxai}"DRYRUN="${DRYRUN:-0}"ISSUES_FILE="${ISSUES_FILE:-scripts/ops/issues-bulk-create.json}"LIMIT="${LIMIT:-500}"   # number of issues to fetch when checking existence# prerequisites checkcommand -v gh >/dev/null 2>&1 || { echo "ERROR: gh CLI is required. https://cli.github.com/"; exit 1; }command -v jq >/dev/null 2>&1 || { echo "ERROR: jq is required. https://stedolan.github.io/jq/"; exit 1; }# helper: return issue number if a matching title exists (exact match)issue_exists() {  local title="$1"  gh issue list --repo "$REPO" --state all --json title,number --limit "$LIMIT" |    jq -r --arg t "$title" '.[] | select(.title == $t) | .number' | head -n1 || true}# helper: create an issue or print command in DRYRUN modecreate_issue() {  local title="$1" body="$2" labels_csv="$3" milestone="$4"  existing="$(issue_exists "$title")"  if [ -n "$existing" ]; then    echo "? Issue exists: #$existing — $title"    return 0  fi  args=(--repo "$REPO" --title "$title" --body "$body")  if [ -n "$labels_csv" ] && [ "$labels_csv" != "null" ]; then    args+=(--label "$labels_csv")  fi  if [ -n "$milestone" ] && [ "$milestone" != "null" ]; then    args+=(--milestone "$milestone")  fi  if [ "$DRYRUN" = "1" ]; then    echo "DRYRUN: gh issue create ${args[*]}"  else    echo "Creating issue: $title"    gh issue create "${args[@]}" >/dev/null && echo "? Created: $title"  fi}# load issues JSON (either file or inline default)if [ -f "$ISSUES_FILE" ]; then  issues_json="$(cat "$ISSUES_FILE")"else  read -r -d '' issues_json <<'JSON' || true[  {    "title": "agent-mode: set up hourly health-check (sensory cortex)",    "body": "Implement hourly health-check job for sensory cortex agent. Steps:\\n1. Verify endpoints\\n2. Post telemetry to /telemetry\\n3. Create alert issue on failure\\n\\nSee Agent Mode Launch milestone.",    "labels": ["agent-mode","ops"],    "milestone": "Agent Mode Launch"  },  {    "title": "agent-mode: telemetry-processing disabled remediation task",    "body": "Remediation steps for telemetry_processing_disabled alert:\\n- Check telemetry worker service\\n- Verify queue backlog\\n- Restart worker if necessary\\n\\nAdd runbook and escalate if unresolved.",    "labels": ["agent-mode","alert"],    "milestone": "Agent Mode Launch"  }]JSONfi# iterate and createecho "$issues_json" | jq -c '.[]' | while read -r item; do  title="$(echo "$item" | jq -r '.title')"  body="$(echo "$item" | jq -r '.body')"  labels="$(echo "$item" | jq -r '(.labels // []) | join(",")')"  milestone="$(echo "$item" | jq -r '.milestone // ""')"  create_issue "$title" "$body" "$labels" "$milestone"doneecho "Done."